#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::ifstream file("data.txt");
    std::string line;
    if (file.is_open()) {
        while (getline(file, line)) {
            std::cout << line << std::endl;
        }
        file.close();
    }
    return 0;
}
```

1. הקוד מניח שהמשתמש מזין מספר חיובי n, והלולאה החיצונית רצה n פעמים כדי לחשב את המכפלה של כל המספרים. 2. בתוך הלולאה החיצונית, ישנה לולאה פנימית שמבצעת חישוב של המכפלה על ידי איטרציה משנית, מה שמוביל לכך שמספר הה iterations בתהליך הוא n*n (n בריבוע). 3. דוגמה לקוד היא: 
